select to_char(run_time,'MM-DD HH24:MI') t, status, details->'timing'->>'durationMs' ms, length(details->>'response') len, substr(details->>'response', greatest(1, position('stageMs' in details->>'response')-2), 500) stage_ms from cron_job_audit where run_time >= '2026-11-15 12:30' and run_time < '2026-11-16 12:45' and job_name='/api/v1/db/forge-served-forecast-snapshot' order by run_time
